def _check_hex64(value: Any, field: str) -> str:
    if not isinstance(value, str) or _HEX64_RE.fullmatch(value) is None:
        raise ValueError(f"{field} must be 64 lowercase hexadecimal characters")
    return value


def _check_trace_ref(value: Any, field: str) -> str:
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a string of the form id@ver")
    rule_id, sep, ver = value.rpartition("@")
    if not sep or not rule_id or not ver.isdigit() or int(ver) < 1:
        raise ValueError(f"{field} must be a string of the form id@ver")
    return value


def _normalize_verified_policy(
    value: Any, at: str, field: str
) -> dict[str, Any]:
    """Validate a ``compile_rules`` snapshot structurally and semantically.

    node = registry.get(key)
    if node is not None:
        return node

    truth = True
    running = anchor
    stage_parts: list[str] = []
    sem_stages: list[dict[str, Any]] = []
    semkey_stages: list[tuple[str, Any, Any]] = []
    for index, (at, bundle, diff, prev, dig) in enumerate(rows):
        if not bundle.truth:
            truth = False
        if diff is not None:
            if not diff.truth:
                truth = False
            if index == 0:
                generated = self.generate_diff(
                    diff_level, diff.before_node, diff.after_node
                )
            else:
                generated = self.generate_diff(
                    diff_level, rows[index - 1][1], bundle
                )
            # Equal values resolve to the same registry node, so an
            # identity check stands in for comparing the full canonical
            # JSON text of the declared and regenerated diffs.
            if diff is not generated:
                truth = False
        # Hash the stage payload incrementally from the cached child
        # bytes instead of concatenating a throwaway payload string.
        hasher = hashlib.sha256(running.encode("ascii"))
        hasher.update(b'{"at":')
        hasher.update(_vjs(at).encode("utf-8"))
        hasher.update(b',"bundle":')
        hasher.update(bundle.json.encode("utf-8"))
        hasher.update(b',"diff":')
        hasher.update(
            b"null" if diff is None else diff.json.encode("utf-8")
        )
        hasher.update(b"}")
        recomputed = hasher.hexdigest()
        if prev != running or dig != recomputed:
            truth = False
        running = recomputed
        stage_parts.append(
            '{"at":' + _vjs(at)
            + ',"bundle":' + bundle.json
            + ',"diff":' + ("null" if diff is None else diff.json)
            + ',"previous":' + _vjs(prev)
            + ',"digest":' + _vjs(dig) + "}"
        )
        sem_stages.append(
            {
                "at": at,
                "bundle": bundle.sem,
                "diff": None if diff is None else diff.dsem,
            }
        )
        semkey_stages.append(
            (
                at,
                bundle.semkey,
                None if diff is None else diff.dsemkey,
            )
        )
    if commitment != running:
        truth = False
    if not (start == rows[0][0] and end == rows[-1][0]):
        truth = False

    node = _VNode()
    node.key = key
    node.truth = truth
    node.members = rows
    node.stage_parts = stage_parts
    node.json = "".join(
        [
            '{"start":' + _vjs(start)
            + ',"end":' + _vjs(end)
            + ',"anchor":' + _vjs(anchor)
            + ',"stages":[',
            ",".join(stage_parts),
            '],"commitment":' + _vjs(commitment) + "}",
        ]
    )
    node.sem = {"start": start, "end": end, "stages": sem_stages}
    node.semkey = (tag, start, end, tuple(semkey_stages))
    node.canonical = None
    registry[key] = node
    return node

def evolution_proof(self, value, field):
    return self._proof(
        "p0", self.p0, value, field, _MATRIX_BUNDLE_EVOLUTION_GENESIS,
        lambda v, f: self.matrix_bundle(v, f),
        -1, lambda v, f: self.matrix_diff(v, f),
    )

def chain_proof(self, value, field):
    return self._proof(
        "p1", self.p1, value, field, _CHECKPOINT_CHAIN_GENESIS,
        lambda v, f: self.proof_bundle(0, v, f),
        0, lambda v, f: self.proof_diff(0, v, f),
    )

def bundle_evolution_proof(self, value, field):
    return self._proof(
        "p2", self.p2, value, field, _CHECKPOINT_CHAIN_BUNDLE_EVOLUTION_GENESIS,
        lambda v, f: self.proof_bundle(1, v, f),
        1, lambda v, f: self.proof_diff(1, v, f),
    )

def delivery_window_proof(self, value, field):
    # A window cut from a window-proof bundle evolution report: the
    # stages carry the same level-2 bundles and adjacent level-2 diffs
    # as a p2 window, so only the proof tag/registry are new.
    return self._proof(
        "p3", self.p3, value, field,
        _BUNDLE_EVOLUTION_CHECKPOINT_BUNDLE_EVOLUTION_GENESIS,
        lambda v, f: self.proof_bundle(2, v, f),
        2, lambda v, f: self.proof_diff(2, v, f),
    )

def _chain_report(self, level: int, value: Any, field: str) -> _VNode:
    """Parse a full ``root, stages`` chain report into a truth node.

    Unlike a window proof, a full report always anchors at the 64-zero
    genesis: the first stage's ``diff`` must be ``null`` (a structural
    ``ValueError``), while a merely false first ``previous`` is a broken
    link carried back as ``truth == False``. Structural and
    embedded-credential violations (key sets, time order, hex64 formats,
    a malformed bundle or adjacent diff, or a diff whose embedded
    before/after bundles do not reproduce the neighboring stage bundles)
    raise ``ValueError``; a false bundle member chain, a false or
    non-adjacent/non-canonical diff, a broken stage link/digest, an
    incomplete change list, or a false root is carried back on the node
    as ``truth == False`` so the verifier turns it into ``False`` after
    both inputs validate. Distinct deep window proofs are hash-consed
    across the call, so each is normalized and recomputed only once.
    ``level`` is 2 for window-proof bundle evolution reports and 3 for
    delivery-stage window proof bundle evolution reports.
    """
    genesis, bundle_parse, diff_parse = {
        2: (
            _BUNDLE_EVOLUTION_CHECKPOINT_BUNDLE_EVOLUTION_GENESIS,
            (lambda v, f: self.proof_bundle(2, v, f)),
            (lambda v, f: self.proof_diff(2, v, f)),
        ),
        3: (
            _DELIVERY_BUNDLE_DIFF_EVOLUTION_GENESIS,
            (lambda v, f: self.proof_bundle(3, v, f)),
            (lambda v, f: self.proof_diff(3, v, f)),
        ),
    }[level]
    if not isinstance(value, dict) or set(value) != {"root", "stages"}:
        raise ValueError(
            f"{field} must be a dict with exactly the keys root, stages"
        )
    root = self._hex64(value["root"], f"{field}.root")
    raw_stages = value["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        sf = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != {
            "at", "bundle", "diff", "previous", "digest"
        }:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = self._time(stage["at"], f"{sf}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{sf}.at must be strictly greater than the preceding at"
            )
        prev = self._hex64(stage["previous"], f"{sf}.previous")
        dig = self._hex64(stage["digest"], f"{sf}.digest")
        bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
        if index == 0:
            if stage["diff"] is not None:
                raise ValueError(f"{sf}.diff must be null on the first stage")
            diff_node: _VNode | None = None
        else:
            diff_node = diff_parse(stage["diff"], f"{sf}.diff")
            preceding = rows[-1][1]
            if diff_node.root_after != bundle.root:
                raise ValueError(
                    f"{sf}.diff.after_root must equal this stage bundle root"
                )
            if diff_node.after_node.semkey != bundle.semkey:
                raise ValueError(
                    f"{sf}.diff.after must reproduce this stage bundle"
                )
            if diff_node.root != preceding.root:
                raise ValueError(
                    f"{sf}.diff.before_root must equal the preceding "
                    "stage bundle root"
                )
            if diff_node.before_node.semkey != preceding.semkey:
                raise ValueError(
                    f"{sf}.diff.before must reproduce the preceding "
                    "stage bundle"
                )
        rows.append((at, bundle, diff_node, prev, dig))
        previous_at = at

    truth = True
    running = genesis
    for index, (at, bundle, diff_node, prev, dig) in enumerate(rows):
        if not bundle.truth:
            truth = False
        if diff_node is not None:
            generated = self.generate_diff(level, rows[index - 1][1], bundle)
            if not diff_node.truth or diff_node is not generated:
                truth = False
        hasher = hashlib.sha256(running.encode("ascii"))
        hasher.update(b'{"at":')
        hasher.update(_vjs(at).encode("utf-8"))
        hasher.update(b',"bundle":')
        hasher.update(bundle.json.encode("utf-8"))
        hasher.update(b',"diff":')
        hasher.update(
            b"null" if diff_node is None else diff_node.json.encode("utf-8")
        )
        hasher.update(b"}")
        recomputed = hasher.hexdigest()
        if prev != running or dig != recomputed:
            truth = False
        running = recomputed
    if root != running:
        truth = False

    node = _VNode()
    node.truth = truth
    node.root = root
    node.members = rows
    return node

def bundle_evolution_chain_report(self, value: Any, field: str) -> _VNode:
    """Parse a full window-proof bundle evolution ``root, stages`` report."""
    return self._chain_report(2, value, field)

def delivery_chain_report(self, value: Any, field: str) -> _VNode:
    """Parse a full delivery-stage window proof bundle evolution report."""
    return self._chain_report(3, value, field)

# ----------------------------------------------------- top-level diffs
def top_bundle(self, value: Any, field: str) -> _VNode:
    return self.proof_bundle(2, value, field)

def top_generate(self, before: _VNode, after: _VNode) -> _VNode:
    return self.generate_diff(2, before, after)

def top_parse_diff(self, value: Any, field: str) -> _VNode:
    return self.proof_diff(2, value, field)

def top_delivery_bundle(self, value: Any, field: str) -> _VNode:
    return self.proof_bundle(3, value, field)

def top_generate_delivery_diff(
    self, before: _VNode, after: _VNode
) -> _VNode:
    return self.generate_diff(3, before, after)

def top_parse_delivery_diff(self, value: Any, field: str) -> _VNode:
    return self.proof_diff(3, value, field)

# --------------------------------------------------------- generators
def build_chain(self, level: int, stages: Any, field: str = "stages") -> str:
    """Generate a ``root, stages`` chain report as canonical JSON text.

    Every stage bundle is parsed through the value engine (structural
    and embedded-proof checks) and must recompute as true; the adjacent
    diffs reuse the parsed bundle nodes directly, so no proof is
    normalized or recomputed twice. ``level`` is -1 for matrix bundle
    evolution, 0 for the checkpoint chain, 1 for the chain window

        tag, registry, value, field, bundle_parse, side_parse, strict=False
    )

def generate_diff(self, level, before: _VNode, after: _VNode) -> _VNode:
    """Canonical diff a generator produces from two canonical bundles."""
    if level == -1:
        tag, registry = "mdiff", self.mdiff
    else:
        tag = {0: "d0", 1: "d1", 2: "d2", 3: "d3"}[level]
        registry = (self.d0, self.d1, self.d2, self.d3)[level]
    before_by_id = {m[0]: m for m in before.members}
    after_by_id = {m[0]: m for m in after.members}
    entries: list[tuple[str, str, _VNode | None, _VNode | None]] = []
    for member_id in sorted(set(before_by_id) | set(after_by_id)):
        bm = before_by_id.get(member_id)
        am = after_by_id.get(member_id)
        if bm is not None and am is not None and bm[1].json == am[1].json:
            continue
        kind = "added" if bm is None else "removed" if am is None else "changed"
        entries.append(
            (member_id, kind, None if bm is None else bm[1],
             None if am is None else am[1])
        )
    change_keys = tuple(
        (i, k, None if bn is None else bn.key, None if an is None else an.key)
        for i, k, bn, an in entries
    )
    memo_key = _VKey((tag, before.key, after.key, change_keys))
    memoized = self.gen.get(memo_key)
    if memoized is not None:
        return memoized
    segments = self._diff_five_segments(
        before.root, after.root, before, after, entries
    )
    digest = self._segments_digest(segments)
    full_key = _VKey(
        (tag, before.root, after.root, digest, before.key, after.key,
         change_keys)
    )
    existing = registry.get(full_key)
    if existing is not None:
        self.gen[memo_key] = existing
        return existing
    node, _digest = self._assemble_diff(
        tag, registry, full_key, before.root, after.root, digest,
        before, after, entries, segments=segments,
    )
    node.truth = True
    node.complete = True
    self.gen[memo_key] = node
    return node

# -------------------------------------------------------------- proofs
def _proof(self, tag, registry, value, field, genesis, bundle_parse,
           diff_level, diff_parse):
    if not isinstance(value, dict) or set(value) != {
        "start", "end", "anchor", "stages", "commitment"
    }:
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, anchor, stages, commitment"
        )
    start = self._time(value["start"], f"{field}.start")
    end = self._time(value["end"], f"{field}.end")
    if start > end:
        raise ValueError(f"{field}.start must not be after {field}.end")
    anchor = self._hex64(value["anchor"], f"{field}.anchor")
    commitment = self._hex64(value["commitment"], f"{field}.commitment")
    raw_stages = value["stages"]
    if not isinstance(raw_stages, list) or not raw_stages:
        raise ValueError(f"{field}.stages must be a non-empty list")

    rows: list[tuple[str, _VNode, _VNode | None, str, str]] = []
    previous_at: str | None = None
    for index, stage in enumerate(raw_stages):
        sf = f"{field}.stages[{index}]"
        if not isinstance(stage, dict) or set(stage) != {
            "at", "bundle", "diff", "previous", "digest"
        }:
            raise ValueError(
                f"{sf} must be a dict with exactly the keys "
                "at, bundle, diff, previous, digest"
            )
        at = self._time(stage["at"], f"{sf}.at")
        if previous_at is not None and at <= previous_at:
            raise ValueError(
                f"{sf}.at must be strictly greater than the preceding stage at"
            )
        prev = self._hex64(stage["previous"], f"{sf}.previous")
        dig = self._hex64(stage["digest"], f"{sf}.digest")
        bundle = bundle_parse(stage["bundle"], f"{sf}.bundle")
        diff: _VNode | None
        if index == 0 and prev == genesis:
            if stage["diff"] is not None:
                raise ValueError(f"{sf}.diff must be null at the genesis stage")
            diff = None
        else:
            diff = diff_parse(stage["diff"], f"{sf}.diff")
            if diff.root_after != bundle.root:
                raise ValueError(
                    f"{sf}.diff.after_root must equal this stage bundle root"
                )
            if diff.after_node.semkey != bundle.semkey:
                raise ValueError(
                    f"{sf}.diff.after must reproduce this stage bundle"
                )
            if index > 0:
                preceding_bundle = rows[-1][1]
                if diff.root != preceding_bundle.root:
                    raise ValueError(
                        f"{sf}.diff.before_root must equal the preceding "
                        "stage bundle root"
                    )
                if diff.before_node.semkey != preceding_bundle.semkey:
                    raise ValueError(
                        f"{sf}.diff.before must reproduce the preceding "
                        "stage bundle"
                    )
        rows.append((at, bundle, diff, prev, dig))
        previous_at = at

    key = _VKey(
        (
            tag, start, end, anchor, commitment,
            tuple(
                (at, b.key, None if d is None else d.key, p, h)
                for at, b, d, p, h in rows
            ),
        )
    )

        return False
    return True


